import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`sprint-planning-doc`,heroTitle:`Build your sprint plan in minutes`,heroSubtitle:`Perplexity Computer turns a raw backlog into a balanced sprint plan with dependency notes, capacity allocation, and risk flags your team can review immediately.`,inputUrlCta:`Plan this sprint`,inputUrlPlaceholder:`e.g. linear.app/... or jira.com/...`,inputUrlPrefill:`Go to {url} and build a sprint planning document. (1) Analyze the candidate tickets, objectives, and blockers in the backlog. (2) Identify dependencies, shared work, and items that should not be scheduled together. (3) Estimate complexity using similar work patterns and relative effort. (4) Group the work into a balanced two-week sprint with goals, capacity allocation, and sequencing. (5) Flag risk areas, spillover candidates, and decisions that should be made before the sprint starts. (6) Deliver a planning document the team can use in sprint kickoff.`,heroOverlaySteps:[`Reviewing backlog candidates, owners, and what the sprint needs to accomplish`,`Mapping dependencies, sequencing constraints, and likely complexity across tickets`,`Balancing capacity across the sprint and identifying risks before kickoff`,`Sprint goals, ticket grouping, and planning notes ready for standup`],generatingSteps:[`Inspecting {url} to understand the backlog, active constraints, and sprint objectives`,`Designing an agent to map dependencies, estimate effort, and sequence candidate work`,`Configuring the sprint plan with capacity allocation, risk flags, and spillover notes`,`Packaging the work into a planning doc your team can review during sprint kickoff`],featureSectionTitle:`From backlog pile to realistic sprint`,featureCardTitles:[`Connects to your planning stack`,`Outputs your team can review together`],featureCardDescriptions:[`Computer breaks the work into backlog analysis, dependency mapping, effort estimation, and sequencing so the sprint plan reflects actual delivery constraints.`,`Linear, Jira, Docs, Notion, and standup notes can stay connected so planning decisions show up in the tools your team already uses.`,`Sprint goals. Ticket grouping. Capacity plan. Dependency notes. Risk flags. Computer delivers a planning document your team can react to immediately.`],capabilitySectionTitle:`Your sprint planner, on autopilot`,capabilitySectionSubtitle:`Paste the backlog, step away, and come back to a balanced sprint plan.`,capabilityCards:[{title:`Backlog Triage`,description:`Computer can sort candidate tickets by relevance, urgency, and fit for the sprint so planning starts from a clean working set.`},{title:`Dependency Mapping`,description:`Computer can identify blockers, shared dependencies, and sequencing issues that would otherwise surface midway through the sprint.`},{title:`Capacity Balancing`,description:`Computer can group the work into a realistic sprint based on complexity, team bandwidth, and risk concentration.`},{title:`Connect Your Tools`,description:`Computer can organize the plan across ticketing systems, Docs, and notes so planning and execution stay aligned.`},{title:`Risk Flagging`,description:`Computer can highlight tickets likely to slip, decisions that need resolution, and work better held for the next sprint.`},{title:`Mid-Sprint Updates`,description:`Computer can revisit the plan later, reflow the sprint, and explain what should move when priorities or capacity change.`}]});export{t as default};
